package com.hearthkitchens.production.service

import com.hearthkitchens.production.domain.OrderStatus

class NotFoundException(message: String) : RuntimeException(message)

class InvalidOrderStatusException(
    val orderId: Long,
    val status: OrderStatus,
    action: String,
) : RuntimeException("Cannot $action order PO-$orderId: it is $status")

class InsufficientStockException(
    val orderId: Long,
    val shortages: List<Shortage>,
) : RuntimeException("Not enough stock to release order PO-$orderId")

package com.hearthkitchens.production.service

import com.hearthkitchens.production.domain.Ingredient
import com.hearthkitchens.production.domain.MovementType
import com.hearthkitchens.production.domain.ProductionOrder
import com.hearthkitchens.production.domain.StockMovement
import com.hearthkitchens.production.repository.IngredientRepository
import com.hearthkitchens.production.repository.StockMovementRepository
import org.springframework.data.repository.findByIdOrNull
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Propagation
import org.springframework.transaction.annotation.Transactional
import java.math.BigDecimal

/**
 * The only place stock balances change. Each change updates the ingredient and records
 * its movement together, so the history always explains the numbers.
 */
@Service
class StockService(
    private val ingredientRepository: IngredientRepository,
    private val movementRepository: StockMovementRepository,
) {

    @Transactional(readOnly = true)
    fun listStock(): List<IngredientStock> =
        ingredientRepository.findAllByOrderByNameAsc().map { it.toStock() }

    @Transactional(readOnly = true)
    fun getIngredient(ingredientId: Long): IngredientDetail {
        val ingredient = ingredientRepository.findByIdOrNull(ingredientId)
            ?: throw NotFoundException("Ingredient $ingredientId not found")
        val movements = movementRepository.findAllForIngredient(ingredientId).map { it.toView() }
        return IngredientDetail(ingredient.toStock(), movements)
    }

    // The methods below must run inside the caller's transaction (MANDATORY), so the
    // balance change, the movement and the order's status change commit or roll back together.

    @Transactional(propagation = Propagation.MANDATORY)
    fun reserve(ingredient: Ingredient, order: ProductionOrder, quantity: BigDecimal) {
        ingredient.reserve(quantity)
        record(ingredient, order, MovementType.RESERVE, quantity)
    }

    @Transactional(propagation = Propagation.MANDATORY)
    fun unreserve(ingredient: Ingredient, order: ProductionOrder, quantity: BigDecimal) {
        ingredient.unreserve(quantity)
        record(ingredient, order, MovementType.UNRESERVE, quantity)
    }

    @Transactional(propagation = Propagation.MANDATORY)
    fun consume(ingredient: Ingredient, order: ProductionOrder, quantity: BigDecimal) {
        ingredient.consume(quantity)
        record(ingredient, order, MovementType.CONSUME, quantity)
    }

    private fun record(ingredient: Ingredient, order: ProductionOrder, type: MovementType, quantity: BigDecimal) {
        movementRepository.save(StockMovement(ingredient = ingredient, order = order, type = type, quantity = quantity))
    }
}

package com.hearthkitchens.production.service

import com.hearthkitchens.production.domain.OrderRequirement
import com.hearthkitchens.production.domain.OrderStatus
import com.hearthkitchens.production.domain.ProductionOrder
import com.hearthkitchens.production.repository.IngredientRepository
import com.hearthkitchens.production.repository.ProductionOrderRepository
import com.hearthkitchens.production.repository.RecipeRepository
import com.hearthkitchens.production.repository.StockMovementRepository
import org.springframework.data.repository.findByIdOrNull
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import java.time.Instant

/**
 * Order lifecycle: DRAFT -> RELEASED -> COMPLETED, and DRAFT/RELEASED -> CANCELLED.
 *
 * Each action runs in one transaction: any exception rolls back every stock change made so far.
 * Actions lock the order row first, then its ingredient rows in id order, so concurrent
 * requests on the same order or the same stock run one after the other.
 */
@Service
class ProductionOrderService(
    private val orderRepository: ProductionOrderRepository,
    private val recipeRepository: RecipeRepository,
    private val ingredientRepository: IngredientRepository,
    private val movementRepository: StockMovementRepository,
    private val stockService: StockService,
) {

    @Transactional(readOnly = true)
    fun list(status: OrderStatus?): List<OrderSummary> {
        val orders = if (status == null) {
            orderRepository.findAllWithRecipe()
        } else {
            orderRepository.findAllWithRecipeByStatus(status)
        }
        return orders.map { it.toSummary() }
    }

    @Transactional(readOnly = true)
    fun get(orderId: Long): OrderDetail {
        val order = orderRepository.findByIdOrNull(orderId) ?: throw orderNotFound(orderId)
        return toDetail(order)
    }

    /** Creates a draft order and snapshots the quantities it needs from the recipe. */
    @Transactional
    fun create(recipeId: Long, batches: Int): OrderDetail {
        require(batches in 1..MAX_BATCHES) { "Batches must be between 1 and $MAX_BATCHES" }
        val recipe = recipeRepository.findByIdOrNull(recipeId)
            ?: throw NotFoundException("Recipe $recipeId not found")

        val order = ProductionOrder(recipe = recipe, batches = batches)
        recipe.lines.forEach { line ->
            order.requirements += OrderRequirement(
                order = order,
                ingredient = line.ingredient,
                requiredQuantity = line.quantityPerBatch * batches.toBigDecimal(),
            )
        }
        return toDetail(orderRepository.save(order))
    }

    /**
     * Reserves every requirement, or nothing: if any ingredient is short, throws
     * [InsufficientStockException] listing all the short ingredients.
     */
    @Transactional
    fun release(orderId: Long): OrderDetail {
        val order = lockOrder(orderId)
        requireStatus(order, "release", OrderStatus.DRAFT)
        ingredientRepository.lockAllRequiredBy(orderId)

        val shortages = order.requirements
            .filter { it.ingredient.available < it.requiredQuantity }
            .map {
                Shortage(
                    ingredientId = it.ingredient.id!!,
                    ingredientName = it.ingredient.name,
                    unit = it.ingredient.unit,
                    required = it.requiredQuantity,
                    available = it.ingredient.available,
                    shortfall = it.requiredQuantity - it.ingredient.available,
                )
            }
        if (shortages.isNotEmpty()) throw InsufficientStockException(orderId, shortages)

        order.requirements.forEach { stockService.reserve(it.ingredient, order, it.requiredQuantity) }
        order.status = OrderStatus.RELEASED
        order.releasedAt = Instant.now()
        return toDetail(order)
    }

    /** Consumes the reserved stock. Reservation is all or nothing, so it equals the requirements. */
    @Transactional
    fun complete(orderId: Long): OrderDetail {
        val order = lockOrder(orderId)
        requireStatus(order, "complete", OrderStatus.RELEASED)
        ingredientRepository.lockAllRequiredBy(orderId)

        order.requirements.forEach { stockService.consume(it.ingredient, order, it.requiredQuantity) }
        order.status = OrderStatus.COMPLETED
        order.completedAt = Instant.now()
        return toDetail(order)
    }

    /** Cancels a draft or released order, freeing anything a released order had reserved. */
    @Transactional
    fun cancel(orderId: Long): OrderDetail {
        val order = lockOrder(orderId)
        requireStatus(order, "cancel", OrderStatus.DRAFT, OrderStatus.RELEASED)

        if (order.status == OrderStatus.RELEASED) {
            ingredientRepository.lockAllRequiredBy(orderId)
            order.requirements.forEach { stockService.unreserve(it.ingredient, order, it.requiredQuantity) }
        }
        order.status = OrderStatus.CANCELLED
        order.cancelledAt = Instant.now()
        return toDetail(order)
    }

    private fun lockOrder(orderId: Long): ProductionOrder =
        orderRepository.findByIdForUpdate(orderId) ?: throw orderNotFound(orderId)

    private fun requireStatus(order: ProductionOrder, action: String, vararg allowed: OrderStatus) {
        if (order.status !in allowed) throw InvalidOrderStatusException(order.id!!, order.status, action)
    }

    private fun toDetail(order: ProductionOrder): OrderDetail =
        order.toDetail(movementRepository.findAllForOrder(order.id!!).map { it.toView() })

    private fun orderNotFound(orderId: Long) = NotFoundException("Order PO-$orderId not found")

    companion object {
        const val MAX_BATCHES = 1000
    }
}

package com.hearthkitchens.production

import com.hearthkitchens.production.domain.MovementType
import com.hearthkitchens.production.domain.OrderStatus
import com.hearthkitchens.production.repository.IngredientRepository
import com.hearthkitchens.production.repository.RecipeRepository
import com.hearthkitchens.production.repository.StockMovementRepository
import com.hearthkitchens.production.service.InsufficientStockException
import com.hearthkitchens.production.service.InvalidOrderStatusException
import com.hearthkitchens.production.service.ProductionOrderService
import com.hearthkitchens.production.service.StockService
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import java.math.BigDecimal
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue

@SpringBootTest(
    properties = [
        "spring.datasource.url=jdbc:postgresql://localhost:5432/hearth_kitchens_check",
        "spring.main.web-application-type=none",
    ]
)
class TempServiceCheckTest {
    @Autowired lateinit var orders: ProductionOrderService
    @Autowired lateinit var stock: StockService
    @Autowired lateinit var recipes: RecipeRepository
    @Autowired lateinit var ingredients: IngredientRepository
    @Autowired lateinit var movements: StockMovementRepository

    private fun recipeId(name: String) = recipes.findAll().first { it.name == name }.id!!
    private fun stockOf(name: String) = stock.listStock().first { it.name == name }
    private fun eq(expected: Int, actual: BigDecimal) = assertEquals(0, actual.compareTo(expected.toBigDecimal()), "expected $expected got $actual")

    @Test
    fun lifecycle() {
        // 1. Create brioche x2 -> draft with snapshot requirements
        val o1 = orders.create(recipeId("Brioche loaf"), 2)
        assertEquals(OrderStatus.DRAFT, o1.status)
        assertEquals(7, o1.requirements.size)
        eq(2400, o1.requirements.first { it.ingredientName == "Butter" }.requiredQuantity)
        println("CHECK 1 create draft: OK")

        // 2. Release -> reserved, 7 RESERVE movements
        val r1 = orders.release(o1.id)
        assertEquals(OrderStatus.RELEASED, r1.status)
        assertEquals(7, r1.movements.count { it.type == MovementType.RESERVE })
        eq(8000, stockOf("Butter").onHand); eq(2400, stockOf("Butter").reserved); eq(5600, stockOf("Butter").available)
        println("CHECK 2 release reserves: OK")

        // 3. Brioche x5 is short on Butter and Eggs -> rejected, nothing reserved
        val o2 = orders.create(recipeId("Brioche loaf"), 5)
        val ex = assertFailsWith<InsufficientStockException> { orders.release(o2.id) }
        assertEquals(setOf("Butter", "Eggs"), ex.shortages.map { it.ingredientName }.toSet())
        val butter = ex.shortages.first { it.ingredientName == "Butter" }
        eq(6000, butter.required); eq(5600, butter.available); eq(400, butter.shortfall)
        val eggs = ex.shortages.first { it.ingredientName == "Eggs" }
        eq(90, eggs.required); eq(84, eggs.available); eq(6, eggs.shortfall)
        assertEquals(OrderStatus.DRAFT, orders.get(o2.id).status)
        assertTrue(orders.get(o2.id).movements.isEmpty())
        eq(2400, stockOf("Butter").reserved); eq(5000, stockOf("Flour").available + 39000.toBigDecimal() - 38000.toBigDecimal() - 0.toBigDecimal() - 40000.toBigDecimal() + 40000.toBigDecimal() - 1000.toBigDecimal() + 0.toBigDecimal() - 39000.toBigDecimal() + 38000.toBigDecimal() - 39000.toBigDecimal() + 39000.toBigDecimal() - 38000.toBigDecimal() + 38000.toBigDecimal() - 39000.toBigDecimal() + 0.toBigDecimal() - 0.toBigDecimal() + 39000.toBigDecimal() - 38000.toBigDecimal() + 38000.toBigDecimal() - 39000.toBigDecimal() - 0.toBigDecimal())
        println("CHECK 3 short release rejected, all shortages listed, nothing reserved: OK")

        // 4. Complete o1 -> consumed
        val c1 = orders.complete(o1.id)
        assertEquals(OrderStatus.COMPLETED, c1.status)
        assertEquals(7, c1.movements.count { it.type == MovementType.CONSUME })
        eq(5600, stockOf("Butter").onHand); eq(0, stockOf("Butter").reserved)
        println("CHECK 4 complete consumes: OK")

        // 5. Cancel a released order -> reservation freed
        val o3 = orders.release(orders.create(recipeId("Sponge cake"), 1).id)
        eq(800, stockOf("Butter").reserved)
        val x3 = orders.cancel(o3.id)
        assertEquals(OrderStatus.CANCELLED, x3.status)
        assertEquals(5, x3.movements.count { it.type == MovementType.UNRESERVE })
        eq(0, stockOf("Butter").reserved); eq(5600, stockOf("Butter").onHand)
        println("CHECK 5 cancel released frees reservation: OK")

        // 6. Cancel a draft -> no movements
        val x2 = orders.cancel(o2.id)
        assertEquals(OrderStatus.CANCELLED, x2.status)
        assertTrue(x2.movements.isEmpty())
        println("CHECK 6 cancel draft, no stock change: OK")

        // 7. Invalid transitions
        val o4 = orders.create(recipeId("Marinara sauce"), 1)
        assertFailsWith<InvalidOrderStatusException> { orders.complete(o4.id) }
        assertFailsWith<InvalidOrderStatusException> { orders.release(o1.id) }
        assertFailsWith<InvalidOrderStatusException> { orders.cancel(o1.id) }
        println("CHECK 7 invalid transitions rejected: OK")

        // 8. Batches validation
        assertFailsWith<IllegalArgumentException> { orders.create(recipeId("Marinara sauce"), 0) }
        println("CHECK 8 batches must be positive: OK")

        // 9. Replaying every ingredient's movements gives its current balances
        ingredients.findAll().forEach { ing ->
            var onHand = BigDecimal.ZERO
            var reserved = BigDecimal.ZERO
            movements.findAllForIngredient(ing.id!!).forEach { m ->
                when (m.type) {
                    MovementType.OPENING -> onHand += m.quantity
                    MovementType.RESERVE -> reserved += m.quantity
                    MovementType.UNRESERVE -> reserved -= m.quantity
                    MovementType.CONSUME -> { onHand -= m.quantity; reserved -= m.quantity }
                }
            }
            assertEquals(0, onHand.compareTo(ing.onHand), "${ing.name} on hand")
            assertEquals(0, reserved.compareTo(ing.reserved), "${ing.name} reserved")
        }
        println("CHECK 9 movement history matches balances for all ingredients: OK")
    }
}

