import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    // Forward API calls to the Spring Boot backend, so the browser sees one origin (no CORS).
    proxy: {
      '/api': 'http://localhost:8080',
    },
  },
})

// Types mirror the backend read models. Quantities are in the ingredient's base unit (g, ml, pcs).

export type BaseUnit = 'G' | 'ML' | 'PCS'
export type OrderStatus = 'DRAFT' | 'RELEASED' | 'COMPLETED' | 'CANCELLED'
export type MovementType = 'OPENING' | 'RESERVE' | 'UNRESERVE' | 'CONSUME'

export const ORDER_STATUSES: OrderStatus[] = ['DRAFT', 'RELEASED', 'COMPLETED', 'CANCELLED']

/** Same limit the backend enforces. */
export const MAX_BATCHES = 1000

export interface IngredientStock {
  id: number
  name: string
  unit: BaseUnit
  onHand: number
  reserved: number
  available: number
}

export interface Movement {
  id: number
  type: MovementType
  quantity: number
  createdAt: string
  ingredientId: number
  ingredientName: string
  unit: BaseUnit
  orderId: number | null
}

export interface IngredientDetail {
  stock: IngredientStock
  movements: Movement[]
}

export interface RecipeLine {
  ingredientId: number
  ingredientName: string
  unit: BaseUnit
  quantityPerBatch: number
}

export interface Recipe {
  id: number
  name: string
  yieldQuantity: number
  yieldUnit: string
  lines: RecipeLine[]
}

export interface OrderSummary {
  id: number
  recipeName: string
  batches: number
  status: OrderStatus
  createdAt: string
}

export interface Requirement {
  ingredientId: number
  ingredientName: string
  unit: BaseUnit
  requiredQuantity: number
  available: number
}

export interface OrderDetail {
  id: number
  recipeId: number
  recipeName: string
  yieldQuantity: number
  yieldUnit: string
  batches: number
  status: OrderStatus
  createdAt: string
  releasedAt: string | null
  completedAt: string | null
  cancelledAt: string | null
  requirements: Requirement[]
  movements: Movement[]
}

export interface Shortage {
  ingredientId: number
  ingredientName: string
  unit: BaseUnit
  required: number
  available: number
  shortfall: number
}

/** Error from the API. `message` is the problem detail; `shortages` is set when a release is rejected. */
export class ApiError extends Error {
  status: number
  shortages: Shortage[]

  constructor(status: number, message: string, shortages: Shortage[] = []) {
    super(message)
    this.status = status
    this.shortages = shortages
  }
}

async function request<T>(method: 'GET' | 'POST', path: string, body?: unknown): Promise<T> {
  const response = await fetch(`/api${path}`, {
    method,
    headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  if (!response.ok) {
    const problem = await response.json().catch(() => ({}))
    throw new ApiError(response.status, problem.detail ?? `Request failed (${response.status})`, problem.shortages ?? [])
  }
  return response.json()
}

export const api = {
  listStock: () => request<IngredientStock[]>('GET', '/ingredients'),
  getIngredient: (id: number) => request<IngredientDetail>('GET', `/ingredients/${id}`),
  listRecipes: () => request<Recipe[]>('GET', '/recipes'),
  listOrders: (status?: OrderStatus) =>
    request<OrderSummary[]>('GET', status ? `/orders?status=${status}` : '/orders'),
  getOrder: (id: number) => request<OrderDetail>('GET', `/orders/${id}`),
  createOrder: (recipeId: number, batches: number) =>
    request<OrderDetail>('POST', '/orders', { recipeId, batches }),
  releaseOrder: (id: number) => request<OrderDetail>('POST', `/orders/${id}/release`),
  completeOrder: (id: number) => request<OrderDetail>('POST', `/orders/${id}/complete`),
  cancelOrder: (id: number) => request<OrderDetail>('POST', `/orders/${id}/cancel`),
}

import type { BaseUnit, MovementType, OrderStatus } from './api'

// Stock is stored in g / ml / pcs but shown in kg / L / pcs, like the brief's seed table.
const DISPLAY_UNITS: Record<BaseUnit, { label: string; factor: number }> = {
  G: { label: 'kg', factor: 1000 },
  ML: { label: 'L', factor: 1000 },
  PCS: { label: 'pcs', factor: 1 },
}

function displayNumber(quantity: number, unit: BaseUnit): string {
  return (quantity / DISPLAY_UNITS[unit].factor).toLocaleString(undefined, { maximumFractionDigits: 3 })
}

export function formatQuantity(quantity: number, unit: BaseUnit): string {
  return `${displayNumber(quantity, unit)} ${DISPLAY_UNITS[unit].label}`
}

/** "+2.4 kg", "−2.4 kg", or "—" for no change. */
export function formatChange(change: number, unit: BaseUnit): string {
  if (change === 0) return '—'
  const sign = change > 0 ? '+' : '−'
  return `${sign}${formatQuantity(Math.abs(change), unit)}`
}

export function formatDateTime(iso: string): string {
  return new Date(iso).toLocaleString()
}

export function orderRef(id: number): string {
  return `PO-${id}`
}

export function statusLabel(status: OrderStatus): string {
  return status.charAt(0) + status.slice(1).toLowerCase()
}

export const MOVEMENT_LABELS: Record<MovementType, string> = {
  OPENING: 'Opening stock',
  RESERVE: 'Reserved',
  UNRESERVE: 'Reservation freed',
  CONSUME: 'Consumed',
}

/** What a movement's quantity does to on hand and reserved (same rules as the backend). */
export const MOVEMENT_EFFECTS: Record<MovementType, { onHand: number; reserved: number }> = {
  OPENING: { onHand: 1, reserved: 0 },
  RESERVE: { onHand: 0, reserved: 1 },
  UNRESERVE: { onHand: 0, reserved: -1 },
  CONSUME: { onHand: -1, reserved: -1 },
}

import { useEffect, useState } from 'react'

/**
 * Loads data when the component mounts and again whenever `deps` change.
 * Responses that arrive after deps have changed are ignored, so a slow old request
 * can't overwrite a newer one.
 */
export function useLoad<T>(load: () => Promise<T>, deps: unknown[]) {
  const [data, setData] = useState<T>()
  const [error, setError] = useState<string>()

  useEffect(() => {
    let current = true
    setError(undefined)
    load().then(
      (result) => current && setData(result),
      (err: Error) => current && setError(err.message),
    )
    return () => {
      current = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)

  return { data, setData, error }
}

import type { OrderStatus, Shortage } from './api'
import { formatQuantity, statusLabel } from './format'

export function StatusBadge({ status }: { status: OrderStatus }) {
  return <span className={`badge badge-${status.toLowerCase()}`}>{statusLabel(status)}</span>
}

export function ErrorMessage({ message }: { message?: string }) {
  return message ? <p className="error">{message}</p> : null
}

export function Loading() {
  return <p className="muted">Loading…</p>
}

export function ShortageTable({ shortages }: { shortages: Shortage[] }) {
  return (
    <div className="panel panel-error">
      <strong>Release rejected: not enough stock. Nothing was reserved.</strong>
      <table>
        <thead>
          <tr>
            <th>Ingredient</th>
            <th className="num">Required</th>
            <th className="num">Available</th>
            <th className="num">Shortfall</th>
          </tr>
        </thead>
        <tbody>
          {shortages.map((s) => (
            <tr key={s.ingredientId}>
              <td>{s.ingredientName}</td>
              <td className="num">{formatQuantity(s.required, s.unit)}</td>
              <td className="num">{formatQuantity(s.available, s.unit)}</td>
              <td className="num short">{formatQuantity(s.shortfall, s.unit)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

import { Link, useSearchParams } from 'react-router-dom'
import { ORDER_STATUSES, api, type OrderStatus } from '../api'
import { ErrorMessage, Loading, StatusBadge } from '../components'
import { formatDateTime, orderRef, statusLabel } from '../format'
import { useLoad } from '../useLoad'

export default function OrdersPage() {
  // The filter lives in the URL (?status=RELEASED) so it survives reloads and back/forward.
  const [params, setParams] = useSearchParams()
  const param = params.get('status')
  const status = ORDER_STATUSES.find((s) => s === param)
  const { data: orders, error } = useLoad(() => api.listOrders(status), [status])

  const filters: (OrderStatus | undefined)[] = [undefined, ...ORDER_STATUSES]

  return (
    <>
      <div className="title-row">
        <h1>Production orders</h1>
        <Link className="button" to="/orders/new">New order</Link>
      </div>

      <div className="filters">
        {filters.map((s) => (
          <button
            key={s ?? 'ALL'}
            className={s === status ? 'active' : ''}
            onClick={() => setParams(s ? { status: s } : {})}
          >
            {s ? statusLabel(s) : 'All'}
          </button>
        ))}
      </div>

      <ErrorMessage message={error} />
      {!orders && !error && <Loading />}
      {orders && orders.length === 0 && <p className="muted">No orders.</p>}
      {orders && orders.length > 0 && (
        <table>
          <thead>
            <tr>
              <th>Order</th>
              <th>Recipe</th>
              <th className="num">Batches</th>
              <th>Status</th>
              <th>Created</th>
            </tr>
          </thead>
          <tbody>
            {orders.map((o) => (
              <tr key={o.id}>
                <td>
                  <Link to={`/orders/${o.id}`}>{orderRef(o.id)}</Link>
                </td>
                <td>{o.recipeName}</td>
                <td className="num">{o.batches}</td>
                <td>
                  <StatusBadge status={o.status} />
                </td>
                <td>{formatDateTime(o.createdAt)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  )
}

import { useState, type FormEvent } from 'react'
import { useNavigate } from 'react-router-dom'
import { MAX_BATCHES, api } from '../api'
import { ErrorMessage, Loading } from '../components'
import { formatQuantity } from '../format'
import { useLoad } from '../useLoad'

export default function CreateOrderPage() {
  const navigate = useNavigate()
  const recipes = useLoad(api.listRecipes, [])
  const stock = useLoad(api.listStock, [])

  const [recipeId, setRecipeId] = useState<number>()
  const [batches, setBatches] = useState('1')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string>()

  const recipe = recipes.data?.find((r) => r.id === recipeId)
  const batchCount = Number(batches)
  const batchesValid = Number.isInteger(batchCount) && batchCount >= 1 && batchCount <= MAX_BATCHES
  const availableById = new Map(stock.data?.map((i) => [i.id, i.available]))

  async function submit(event: FormEvent) {
    event.preventDefault()
    if (!recipe || !batchesValid) return
    setSubmitting(true)
    setError(undefined)
    try {
      const order = await api.createOrder(recipe.id, batchCount)
      navigate(`/orders/${order.id}`)
    } catch (err) {
      setError((err as Error).message)
      setSubmitting(false)
    }
  }

  if (recipes.error) return <ErrorMessage message={recipes.error} />
  if (!recipes.data) return <Loading />

  return (
    <>
      <h1>New production order</h1>
      <form className="form" onSubmit={submit}>
        <label>
          Recipe
          <select value={recipeId ?? ''} onChange={(e) => setRecipeId(Number(e.target.value))} required>
            <option value="" disabled>Choose a recipe</option>
            {recipes.data.map((r) => (
              <option key={r.id} value={r.id}>
                {r.name} ({r.yieldQuantity} {r.yieldUnit} per batch)
              </option>
            ))}
          </select>
        </label>
        <label>
          Batches
          <input
            type="number"
            min={1}
            max={MAX_BATCHES}
            step={1}
            value={batches}
            onChange={(e) => setBatches(e.target.value)}
            required
          />
        </label>
        {!batchesValid && <p className="error">Batches must be a whole number from 1 to {MAX_BATCHES}.</p>}
        <ErrorMessage message={error} />
        <div>
          <button type="submit" disabled={!recipe || !batchesValid || submitting}>
            {submitting ? 'Creating…' : 'Create draft order'}
          </button>
        </div>
      </form>

      {recipe && batchesValid && (
        <>
          <h2>
            Ingredients needed for {batchCount} × {recipe.name} ({recipe.yieldQuantity * batchCount} {recipe.yieldUnit})
          </h2>
          <p className="muted">Creating the order doesn't reserve anything. Stock is checked and reserved when you release it.</p>
          <table>
            <thead>
              <tr>
                <th>Ingredient</th>
                <th className="num">Required</th>
                <th className="num">Available now</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {recipe.lines.map((line) => {
                const required = line.quantityPerBatch * batchCount
                const available = availableById.get(line.ingredientId)
                const short = available !== undefined && available < required
                return (
                  <tr key={line.ingredientId}>
                    <td>{line.ingredientName}</td>
                    <td className="num">{formatQuantity(required, line.unit)}</td>
                    <td className="num">{available === undefined ? '…' : formatQuantity(available, line.unit)}</td>
                    <td className={short ? 'short' : 'ok'}>{available === undefined ? '' : short ? 'Short' : 'OK'}</td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </>
      )}
    </>
  )
}

import { useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { ApiError, api, type OrderDetail, type Shortage } from '../api'
import { ErrorMessage, Loading, ShortageTable, StatusBadge } from '../components'
import { MOVEMENT_LABELS, formatDateTime, formatQuantity, orderRef } from '../format'
import { useLoad } from '../useLoad'

export default function OrderPage() {
  const id = Number(useParams().id)
  const { data: order, setData: setOrder, error } = useLoad(() => api.getOrder(id), [id])

  const [busy, setBusy] = useState(false)
  const [actionError, setActionError] = useState<string>()
  const [shortages, setShortages] = useState<Shortage[]>([])

  async function run(action: (id: number) => Promise<OrderDetail>, confirmText?: string) {
    if (confirmText && !window.confirm(confirmText)) return
    setBusy(true)
    setActionError(undefined)
    setShortages([])
    try {
      setOrder(await action(id))
    } catch (err) {
      setActionError((err as Error).message)
      setShortages(err instanceof ApiError ? err.shortages : [])
      // Refresh in case the order or stock changed since the page loaded.
      api.getOrder(id).then(setOrder, () => {})
    } finally {
      setBusy(false)
    }
  }

  if (error) return <ErrorMessage message={error} />
  if (!order) return <Loading />

  const ref = orderRef(order.id)
  const isDraft = order.status === 'DRAFT'

  return (
    <>
      <p>
        <Link to="/orders">← Orders</Link>
      </p>
      <div className="title-row">
        <h1>
          {ref} · {order.recipeName} × {order.batches}
        </h1>
        <StatusBadge status={order.status} />
      </div>
      <p className="muted">
        Yields {order.yieldQuantity * order.batches} {order.yieldUnit} · Created {formatDateTime(order.createdAt)}
        {order.releasedAt && ` · Released ${formatDateTime(order.releasedAt)}`}
        {order.completedAt && ` · Completed ${formatDateTime(order.completedAt)}`}
        {order.cancelledAt && ` · Cancelled ${formatDateTime(order.cancelledAt)}`}
      </p>

      <div className="actions">
        {order.status === 'DRAFT' && (
          <button disabled={busy} onClick={() => run(api.releaseOrder)}>
            Release
          </button>
        )}
        {order.status === 'RELEASED' && (
          <button
            disabled={busy}
            onClick={() => run(api.completeOrder, `Complete ${ref}? This consumes its reserved stock.`)}
          >
            Complete
          </button>
        )}
        {(order.status === 'DRAFT' || order.status === 'RELEASED') && (
          <button
            className="secondary"
            disabled={busy}
            onClick={() =>
              run(
                api.cancelOrder,
                `Cancel ${ref}?${order.status === 'RELEASED' ? ' Its reserved stock will be freed.' : ''}`,
              )
            }
          >
            Cancel order
          </button>
        )}
        {(order.status === 'COMPLETED' || order.status === 'CANCELLED') && (
          <span className="muted">No further actions for a {order.status.toLowerCase()} order.</span>
        )}
      </div>

      {shortages.length > 0 ? <ShortageTable shortages={shortages} /> : <ErrorMessage message={actionError} />}

      <h2>Ingredient requirements</h2>
      <table>
        <thead>
          <tr>
            <th>Ingredient</th>
            <th className="num">Required</th>
            {isDraft && <th className="num">Available now</th>}
            {isDraft && <th></th>}
          </tr>
        </thead>
        <tbody>
          {order.requirements.map((r) => {
            const short = r.available < r.requiredQuantity
            return (
              <tr key={r.ingredientId}>
                <td>
                  <Link to={`/stock/${r.ingredientId}`}>{r.ingredientName}</Link>
                </td>
                <td className="num">{formatQuantity(r.requiredQuantity, r.unit)}</td>
                {isDraft && <td className="num">{formatQuantity(r.available, r.unit)}</td>}
                {isDraft && <td className={short ? 'short' : 'ok'}>{short ? 'Short' : 'OK'}</td>}
              </tr>
            )
          })}
        </tbody>
      </table>

      <h2>Stock movements</h2>
      {order.movements.length === 0 ? (
        <p className="muted">No stock movements yet. Releasing the order reserves its ingredients.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Ingredient</th>
              <th>Movement</th>
              <th className="num">Quantity</th>
            </tr>
          </thead>
          <tbody>
            {order.movements.map((m) => (
              <tr key={m.id}>
                <td>{formatDateTime(m.createdAt)}</td>
                <td>
                  <Link to={`/stock/${m.ingredientId}`}>{m.ingredientName}</Link>
                </td>
                <td>{MOVEMENT_LABELS[m.type]}</td>
                <td className="num">{formatQuantity(m.quantity, m.unit)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  )
}

